  --accent: oklch(0.8 0.12 60);
  --accent-hover: oklch(0.86 0.1 62);
  --rule: oklch(0.42 0.05 268 / 0.6);

  --serif: "Spectral", Georgia, serif;
  --sans: "Hanken Grotesk", system-ui, sans-serif;

